INSERT INTO public.ai_skills (slug, name, description, category, when_to_use, target_objective, main_instructions, output_format, default_model_profile, status, required_tools, version)
VALUES
  ('ig-reel', 'Roteiro de Reels (26 Hooks)', 'Roteirização de vídeos curtos com fórmulas comprovadas de ganchos magnéticos, beat sheet a 165 WPM e retenção nos 3 primeiros segundos.', 'CONTEÚDO', 'Gravação de Reels educativos, de autoridade ou atração.', 'Reter nos primeiros 3 segundos e maximizar conclusão.', 'Aplique fórmulas de ganchos validados. Sem introduções lentas. Conecte o hook com a resolução em até 10s.', 'json', 'CONTENT_STANDARD', 'published', ARRAY['ai.score_hook', 'ai.generate_beat_sheet', 'company.get_brand_manual', 'criafy.save_content'], 1),
  ('ig-carousel', 'Carrossel Slide a Slide', 'Estruturação completa de carrossel: capa magnética que força o arrasto, lâminas de densidade e CTA final de salvamento.', 'CONTEÚDO', 'Posts educativos, tutoriais e listas aprofundadas.', 'Alto número de salvamentos e compartilhamentos.', 'Crie capa de alto contraste com promessa clara. Divida o conteúdo em 7 a 10 lâminas legíveis.', 'json', 'CONTENT_STANDARD', 'published', ARRAY['company.get_brand_manual', 'criafy.save_content'], 1),
  ('ig-caption', 'Legenda Otimizada (125 chars)', 'Copywriting de legenda com corte visual nos 125 caracteres, parágrafos curtos e até 5 hashtags intencionais.', 'CONTEÚDO', 'Qualquer publicação no feed que demande leitura rápida.', 'Forçar o clique em Mais e engajar no feed.', 'Inicie com gancho curto de 1 linha. Pule linha antes do corpo principal. Termine com CTA único.', 'text', 'CONTENT_STANDARD', 'published', ARRAY['company.get_brand_manual'], 1),
  ('ig-story', 'Sequência de Stories & Funil de DM', 'Narrativa sequencial de 3 a 5 stories diários com enquetes/stickers e gatilho de resposta para o direct.', 'CONTEÚDO', 'Engajamento diário e geração de conversas qualificadas.', 'Taxa de resposta alta no direct e qualificação de leads.', 'Abra com quebra de padrão ou enquete polarizada. Entregue valor intermediário. Chame para responder no direct.', 'text', 'CONTENT_STANDARD', 'published', ARRAY['company.get_brand_manual'], 1),
  ('ig-profile', 'Auditoria de Perfil & Bio (0-100)', 'Rubrica técnica de 0 a 100 pontos avaliando foto, campo nome, bio, destaques e link estratégico.', 'ANÁLISE', 'Diagnóstico e otimização da taxa de conversão do perfil.', 'Transformar visitantes do perfil em seguidores e leads.', 'Analise clareza da proposta de valor, palavras-chave no nome (@) e prova social nos destaques.', 'json', 'STRATEGY_ADVANCED', 'published', ARRAY['company.get_brand_manual', 'instagram.get_metrics'], 1),
  ('ig-viral', 'Modelagem de Conteúdo Viral', 'Mapeamento e desconstrução de padrões e ângulos virais do nicho para modelagem ética sem plágio.', 'ESTRATÉGIA', 'Identificação de tópicos em alta e planejamento de pautas de topo de funil.', 'Atração orgânica de novos seguidores qualificados.', 'Identifique o gatilho emocional de conteúdos em alta. Adapte a mecânica para a autoridade e posicionamento da marca.', 'text', 'STRATEGY_ADVANCED', 'published', ARRAY['company.get_brand_manual'], 1),
  ('ig-human', 'Humanizador Anti-IA', 'Higienização profunda de textos: remove clichês de IA, pontuações excessivas e garante tom natural.', 'CONTEÚDO', 'Revisão final de qualquer texto antes de publicar.', 'Comunicação autêntica, direta e profissional.', 'Corte frases genéricas, adjetivos inflados e construções passivas. Traga o vocabulário real da marca.', 'text', 'CONTENT_STANDARD', 'published', ARRAY[], 1),
  ('ig-plan', 'Planejador Editorial Semanal', 'Matriz semanal distribuindo pilares de Atração, Autoridade e Conversão ao longo dos dias.', 'ESTRATÉGIA', 'Definição da grade semanal de publicações.', 'Consistência e equilíbrio comercial do feed.', 'Distribua 40% autoridade, 40% atração e 20% conversão. Varie formatos entre Reels, Carrossel e Stories.', 'json', 'STRATEGY_ADVANCED', 'published', ARRAY['company.get_brand_manual', 'instagram.get_metrics'], 1),
  ('ig-hooks', 'Laboratório de Ganchos', 'Geração de 5 a 10 variações de ganchos para o mesmo tema usando as 26 fórmulas comprovadas.', 'CONTEÚDO', 'Brainstorming e teste A/B de títulos para Reels e posts.', 'Garantir retenção máxima e taxa de clique.', 'Aplique fórmulas de contraste, números específicos, erros comuns e revelações contra-intuitivas.', 'json', 'CONTENT_STANDARD', 'published', ARRAY['ai.score_hook'], 1),
  ('ig-dm', 'Funil de Conversão via DM', 'Desenvolvimento de palavras-chave para automação e roteiro de qualificação rápida no direct.', 'VENDAS', 'Transformação de comentários em leads no pipeline comercial.', 'Taxa de conversão de comentários em oportunidades reais.', 'Defina a palavra-chave de ativação. Estruture mensagem inicial de acolhimento e pergunta de qualificação.', 'text', 'CONTENT_ADVANCED', 'published', ARRAY['company.get_brand_manual', 'crm.get_lead'], 1),
  ('ig-comment', 'Estratégia de Comentários', 'Respostas estratégicas em comentários que estimulam continuação da conversa e ativam o algoritmo.', 'CONTEÚDO', 'Gestão de comunidade e estímulo ao algoritmo do Instagram.', 'Aumentar tempo de tela e retenção do post.', 'Nunca responda apenas com emojis. Devolva uma pergunta aberta para gerar novo comentário.', 'text', 'FAST_CLASSIFIER', 'published', ARRAY['company.get_brand_manual'], 1),
  ('ig-repurpose', 'Reciclador Multi-formato', 'Transformação de 1 conteúdo validado em múltiplos formatos complementares sem parecer repetitivo.', 'ESTRATÉGIA', 'Multiplicação de produtividade e alcance de conteúdos vencedores.', 'Maximização do ROI de cada tema desenvolvido.', 'Desmembre 1 Reel em 1 Carrossel educativo, 2 posts estáticos de reflexão e 1 sequência de Stories.', 'json', 'CONTENT_STANDARD', 'published', ARRAY['company.get_brand_manual', 'criafy.save_content'], 1),
  ('ig-art', 'Direção Criativa & Visual', 'Briefing estético com enquadramentos, paleta de cores, tipografia e ritmo de corte para designers e videomakers.', 'ESTRATÉGIA', 'Alinhamento visual da produção de conteúdo com a marca.', 'Consistência estética e percepção de alto valor.', 'Defina planos de câmera, elementos gráficos de apoio e ritmo de transição baseados no manual da marca.', 'text', 'CONTENT_STANDARD', 'published', ARRAY['company.get_brand_manual'], 1)
INSERT INTO public.ai_agents (slug, name, description, status, model_profile, system_prompt, skills, tools, context_providers, permissions, version)
VALUES
  ('InstagramReelAgent', 'Roteirista de Reels (ig-reel)', 'Especialista em roteiros de alta retenção para Reels com 26 fórmulas de ganchos comprovadas e beat sheet a 165 WPM.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramReelAgent. Você escreve roteiros magnéticos de Reels focados em retenção nos primeiros 3 segundos e clareza de método.', ARRAY['ig-reel'], ARRAY['ai.score_hook', 'ai.generate_beat_sheet', 'company.get_brand_manual', 'criafy.save_content'], ARRAY['brand_manual', 'account_strategy'], ARRAY['criafy.read', 'criafy.write', 'ai.use_tools'], 1),
  ('InstagramCarouselAgent', 'Arquiteto de Carrossel (ig-carousel)', 'Estruturação slide a slide de carrosséis educativos com foco em alto salvamento e compartilhamento.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramCarouselAgent. Você constrói carrosséis com capas que forçam o arrasto e lâminas com densidade de valor.', ARRAY['ig-carousel'], ARRAY['company.get_brand_manual', 'criafy.save_content'], ARRAY['brand_manual', 'account_strategy'], ARRAY['criafy.read', 'criafy.write', 'ai.use_tools'], 1),
  ('InstagramCaptionAgent', 'Copywriter de Legenda (ig-caption)', 'Redação de legendas persuasivas com corte visual nos primeiros 125 caracteres e CTA único.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramCaptionAgent. Você domina a primeira linha de impacto antes do mais e chamadas de ação diretas.', ARRAY['ig-caption'], ARRAY['company.get_brand_manual'], ARRAY['brand_manual', 'account_strategy'], ARRAY['criafy.read', 'ai.use_tools'], 1),
  ('InstagramStoriesAgent', 'Estrategista de Stories (ig-story)', 'Sequências narrativas de 3 a 5 stories diários com quebra de padrão, enquetes e funil para direct.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramStoriesAgent. Seu objetivo é engajar a audiência existente e gerar conversas no direct.', ARRAY['ig-story'], ARRAY['company.get_brand_manual'], ARRAY['brand_manual', 'account_strategy'], ARRAY['criafy.read', 'ai.use_tools'], 1),
  ('InstagramProfileAgent', 'Auditor de Perfil & Bio (ig-profile)', 'Auditoria completa do perfil com nota 0 a 100 em bio, foto, campo nome e destaques.', 'active', 'STRATEGY_ADVANCED', 'Você é o InstagramProfileAgent. Você audita o perfil do Instagram ajustando a proposta de valor para converter visitantes.', ARRAY['ig-profile'], ARRAY['company.get_brand_manual', 'instagram.get_metrics'], ARRAY['brand_manual', 'instagram_account'], ARRAY['criafy.read', 'ai.use_tools'], 1),
  ('InstagramViralAgent', 'Modelador de Conteúdo Viral (ig-viral)', 'Mapeamento de padrões e ângulos virais do nicho para modelagem estratégica e ética.', 'active', 'STRATEGY_ADVANCED', 'Você é o InstagramViralAgent. Você analisa ganchos e tensões com alto potencial de alcance orgânico.', ARRAY['ig-viral'], ARRAY['company.get_brand_manual'], ARRAY['brand_manual', 'account_strategy'], ARRAY['criafy.read', 'ai.use_tools'], 1),
  ('InstagramHumanizerAgent', 'Humanizador Anti-IA (ig-human)', 'Higienização profunda de textos eliminando jargões robóticos e clichês de IA genérica.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramHumanizerAgent. Você elimina qualquer vestígio de texto robótico tornando a comunicação natural e autêntica.', ARRAY['ig-human'], ARRAY[], ARRAY['brand_manual'], ARRAY['ai.use_tools'], 1),
  ('InstagramPlannerAgent', 'Planejador Editorial (ig-plan)', 'Matriz editorial semanal equilibrando Atração, Autoridade e Conversão no feed.', 'active', 'STRATEGY_ADVANCED', 'Você é o InstagramPlannerAgent. Você desenha a grade editorial semanal garantindo consistência e resultados comerciais.', ARRAY['ig-plan'], ARRAY['company.get_brand_manual', 'instagram.get_metrics'], ARRAY['brand_manual', 'account_strategy', 'content_history'], ARRAY['criafy.read', 'criafy.write', 'ai.use_tools'], 1),
  ('InstagramHooksAgent', 'Especialista em Ganchos (ig-hooks)', 'Laboratório de aberturas de alta retenção baseado nas 26 fórmulas validadas.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramHooksAgent. Você produz variações de ganchos que retêm a atenção nos 3 primeiros segundos.', ARRAY['ig-hooks'], ARRAY['ai.score_hook'], ARRAY['brand_manual'], ARRAY['ai.use_tools'], 1),
  ('InstagramDmFunnelAgent', 'Arquiteto de Funil de DM (ig-dm)', 'Palavras-chave de ativação e scripts de qualificação rápida e humanizada no direct.', 'active', 'CONTENT_ADVANCED', 'Você é o InstagramDmFunnelAgent. Você cria a ponte de conversão entre comentários e conversas no direct.', ARRAY['ig-dm'], ARRAY['company.get_brand_manual', 'crm.get_lead'], ARRAY['brand_manual', 'crm_lead'], ARRAY['criafy.read', 'crm.read', 'ai.use_tools'], 1),
  ('InstagramEngagementAgent', 'Especialista em Comentários (ig-comment)', 'Geração de respostas inteligentes que prolongam o diálogo e ativam o algoritmo.', 'active', 'FAST_CLASSIFIER', 'Você é o InstagramEngagementAgent. Você responde comentários nos posts gerando novas conversas.', ARRAY['ig-comment'], ARRAY['company.get_brand_manual'], ARRAY['brand_manual'], ARRAY['criafy.read', 'ai.use_tools'], 1),
  ('InstagramRepurposerAgent', 'Reciclador Multi-formato (ig-repurpose)', 'Engenharia de reaproveitamento: multiplica 1 ideia vencedora em múltiplos formatos.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramRepurposerAgent. Você extrai o valor máximo de cada ideia excelente em múltiplos canais.', ARRAY['ig-repurpose'], ARRAY['company.get_brand_manual', 'criafy.save_content'], ARRAY['brand_manual', 'account_strategy'], ARRAY['criafy.read', 'criafy.write', 'ai.use_tools'], 1),
  ('InstagramArtDirectorAgent', 'Diretor Criativo & Visual (ig-art)', 'Briefing estético com enquadramentos, paleta, enquadramento e referências visuais.', 'active', 'CONTENT_STANDARD', 'Você é o InstagramArtDirectorAgent. Você orienta a estética da marca garantindo autoridade visual e legibilidade.', ARRAY['ig-art'], ARRAY['company.get_brand_manual'], ARRAY['brand_manual'], ARRAY['criafy.read', 'ai.use_tools'], 1)
