/* ========================================================
   MIGRATION: SEED DAS 13 INSTAGRAM AGENT SKILLS & AGENTES
   Registra todos os 13 agentes e skills especializados da
   suite Instagram Agent Skill no banco de dados.
======================================================== */

-- 1. SEED DAS 13 SKILLS DO INSTAGRAM NO BANCO
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  main_instructions = EXCLUDED.main_instructions,
  required_tools = EXCLUDED.required_tools;

-- 2. SEED DOS 13 AGENTES DO INSTAGRAM NO BANCO
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  system_prompt = EXCLUDED.system_prompt,
  skills = EXCLUDED.skills,
  tools = EXCLUDED.tools;
